sys_security_acl.script:
// ACL script to allow users to modify their own brunch items
// Coordinators can modify all items
function canAccessBrunchItem() {
    // Check if user has brunch coordinator role
    if (gs.hasRole('x_undul_brunch_app.brunch_coordinator')) {
        return true;
    }

    // Check if user is the owner of the brunch item
    if (current.participant_name == gs.getUserID()) {
        return true;
    }

    return false;
}

// Return result for ACL evaluation
canAccessBrunchItem();
